import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`regex-memo.content`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<p><strong>Regular expressions</strong> describe a pattern that text either matches or does not. The syntax below is the JavaScript flavour; PCRE, Python, Go and Java agree on almost all of it — the differences are called out where they bite.</p><pre><code class="language-js">/^\\d{4}-\\d{2}-\\d{2}$/.test(&#39;2026-08-22&#39;); // true
&#39;a1b2&#39;.replace(/\\d/g, &#39;#&#39;); // &#39;a#b#&#39;
</code></pre><h2>🔡 Character Classes</h2><table><thead><tr><th>Expression</th><th>Matches</th></tr></thead><tbody><tr><td><code>.</code></td><td>Any character except a newline (any at all with the <code>s</code> flag)</td></tr><tr><td><code>[A-Za-z]</code></td><td>A letter</td></tr><tr><td><code>[a-z]</code> / <code>[A-Z]</code></td><td>A lower-case / upper-case letter</td></tr><tr><td><code>\\d</code> or <code>[0-9]</code></td><td>A digit</td></tr><tr><td><code>\\D</code> or <code>[^0-9]</code></td><td>Anything but a digit</td></tr><tr><td><code>\\w</code> or <code>[A-Za-z0-9_]</code></td><td>A letter, digit or underscore</td></tr><tr><td><code>\\W</code></td><td>The inverse of <code>\\w</code></td></tr><tr><td><code>\\s</code></td><td>Whitespace: space, tab, newline, carriage return</td></tr><tr><td><code>\\S</code></td><td>The inverse of <code>\\s</code></td></tr><tr><td><code>\\p{L}</code> / <code>\\p{Nd}</code></td><td>Any Unicode letter / decimal digit (needs the <code>u</code> flag)</td></tr><tr><td><code>\\x41</code> / <code>\\u00E9</code></td><td>A character by hex code, or by Unicode code point</td></tr></tbody></table><h2>␣ Whitespace</h2><table><thead><tr><th>Expression</th><th>Matches</th></tr></thead><tbody><tr><td><code></code></td><td>A literal space</td></tr><tr><td><code>\\t</code></td><td>Tab</td></tr><tr><td><code>\\n</code></td><td>Newline</td></tr><tr><td><code>\\r</code></td><td>Carriage return</td></tr><tr><td><code>\\f</code> <code>\\v</code></td><td>Form feed, vertical tab</td></tr><tr><td><code>\\s</code></td><td>Any of the above</td></tr></tbody></table><h2>🎯 Character Sets</h2><table><thead><tr><th>Expression</th><th>Matches</th></tr></thead><tbody><tr><td><code>[xyz]</code></td><td><code>x</code>, <code>y</code> or <code>z</code></td></tr><tr><td><code>[^xyz]</code></td><td>Anything except <code>x</code>, <code>y</code>, <code>z</code></td></tr><tr><td><code>[1-3]</code></td><td><code>1</code>, <code>2</code> or <code>3</code></td></tr><tr><td><code>[^1-3]</code></td><td>Anything except <code>1</code>, <code>2</code>, <code>3</code></td></tr><tr><td><code>[a-z0-9_]</code></td><td>Ranges and single characters can be mixed</td></tr></tbody></table><ul><li>A set is an <strong>or</strong> over single characters — <code>[abc]</code> matches one character, not the string <code>abc</code>.</li><li><code>^</code> right after the opening <code>[</code> negates the set.</li><li>Inside a set, most metacharacters lose their meaning: <code>.</code> is a literal period, <code>+</code> a literal plus.</li></ul><h2>🔒 Escaping</h2><p>Outside a character set, these need a backslash to be taken literally:</p><p>| Escape | Character | Escape | Character | | ------ | -------------------------------------- | ------ | ------------------- | --------------- | | <code>\\.</code> | Period | <code>\\(</code> | Opening parenthesis | | <code>\\^</code> | Caret | <code>\\)</code> | Closing parenthesis | | <code>\\$</code> | Dollar sign | <code>\\[</code> | Opening bracket | | <code>\\\\ | </code> | Pipe | <code>\\]</code> | Closing bracket | | <code>\\\\</code> | Backslash | <code>\\{</code> | Opening brace | | <code>\\/</code> | Forward slash (only in <code>/…/</code> literals) | <code>\\}</code> | Closing brace |</p><p>Inside a character set only <code>\\\\</code> and <code>\\]</code> always need escaping. A <code>^</code> needs it only immediately after <code>[</code>, and a <code>-</code> only between two other characters.</p><h2>🔢 Quantifiers</h2><table><thead><tr><th>Expression</th><th>Repeats the preceding item</th></tr></thead><tbody><tr><td><code>{2}</code></td><td>Exactly twice</td></tr><tr><td><code>{2,}</code></td><td>Two or more times</td></tr><tr><td><code>{2,7}</code></td><td>Between two and seven times</td></tr><tr><td><code>*</code></td><td>Zero or more</td></tr><tr><td><code>+</code></td><td>One or more</td></tr><tr><td><code>?</code></td><td>Zero or once</td></tr><tr><td><code>*?</code> <code>+?</code> <code>??</code> <code>{2,7}?</code></td><td>The lazy form — match as <em>few</em> characters as possible</td></tr></tbody></table><pre><code class="language-js">&#39;&lt;b&gt;bold&lt;/b&gt;&#39;.match(/&lt;.+&gt;/)[0]; // &#39;&lt;b&gt;bold&lt;/b&gt;&#39;  — greedy
&#39;&lt;b&gt;bold&lt;/b&gt;&#39;.match(/&lt;.+?&gt;/)[0]; // &#39;&lt;b&gt;&#39;          — lazy
</code></pre><h2>📍 Anchors &amp; Boundaries</h2><table><thead><tr><th>Expression</th><th>Matches at</th></tr></thead><tbody><tr><td><code>^</code></td><td>Start of the string (start of a line with the <code>m</code> flag)</td></tr><tr><td><code>$</code></td><td>End of the string (end of a line with the <code>m</code> flag)</td></tr><tr><td><code>\\b</code></td><td>A word boundary</td></tr><tr><td><code>\\B</code></td><td>Anywhere that is <em>not</em> a word boundary</td></tr><tr><td><code>\\A</code> <code>\\z</code></td><td>Start / end of the string in PCRE, Python, Java — <strong>not</strong> in JavaScript</td></tr></tbody></table><p>A word boundary sits between a <code>\\w</code> and a <code>\\W</code> (or the edge of the string), so <code>\\bcat\\b</code> matches <code>cat</code> in <code>the cat sat</code> but not in <code>concatenate</code>.</p><h2>🔀 Alternation &amp; Lookaround</h2><table><thead><tr><th>Expression</th><th>Matches</th></tr></thead><tbody><tr><td><code>foo|bar</code></td><td>Either <code>foo</code> or <code>bar</code></td></tr><tr><td><code>foo(?=bar)</code></td><td><code>foo</code> only when followed by <code>bar</code></td></tr><tr><td><code>foo(?!bar)</code></td><td><code>foo</code> only when <strong>not</strong> followed by <code>bar</code></td></tr><tr><td><code>(?&lt;=bar)foo</code></td><td><code>foo</code> only when preceded by <code>bar</code></td></tr><tr><td><code>(?&lt;!bar)foo</code></td><td><code>foo</code> only when <strong>not</strong> preceded by <code>bar</code></td></tr></tbody></table><p>Lookaround is <em>zero-width</em>: it tests the surroundings without consuming them, so nothing it matches ends up in the result.</p><h2>🎁 Groups &amp; Backreferences</h2><table><thead><tr><th>Expression</th><th>Meaning</th></tr></thead><tbody><tr><td><code>(foo)</code></td><td>Capturing group — matches <code>foo</code> and remembers it</td></tr><tr><td><code>(?:foo)</code></td><td>Non-capturing group — groups without capturing</td></tr><tr><td><code>(?&lt;year&gt;\\d{4})</code></td><td>Named capturing group</td></tr><tr><td><code>\\1</code></td><td>Backreference to the first group</td></tr><tr><td><code>\\k&lt;year&gt;</code></td><td>Backreference to a named group</td></tr></tbody></table><pre><code class="language-js">// named groups make replacements readable
&#39;2026-08-22&#39;.replace(/(?&lt;y&gt;\\d{4})-(?&lt;m&gt;\\d{2})-(?&lt;d&gt;\\d{2})/, &#39;$&lt;d&gt;/$&lt;m&gt;/$&lt;y&gt;&#39;);
// &#39;22/08/2026&#39;

const { groups } = /(?&lt;user&gt;\\w+)@(?&lt;host&gt;[\\w.]+)/.exec(&#39;jane@example.com&#39;);
// groups.user === &#39;jane&#39;, groups.host === &#39;example.com&#39;
</code></pre><h2>🚩 Flags</h2><table><thead><tr><th>Flag</th><th>Name</th><th>Effect</th></tr></thead><tbody><tr><td><code>g</code></td><td>global</td><td>Find every match, not just the first</td></tr><tr><td><code>i</code></td><td>ignore case</td><td>Case-insensitive matching</td></tr><tr><td><code>m</code></td><td>multiline</td><td><code>^</code> and <code>$</code> match at line breaks</td></tr><tr><td><code>s</code></td><td>dotAll</td><td><code>.</code> also matches newlines</td></tr><tr><td><code>u</code></td><td>unicode</td><td>Treat the pattern as Unicode code points; enables <code>\\p{…}</code></td></tr><tr><td><code>y</code></td><td>sticky</td><td>Match only from <code>lastIndex</code>, no scanning ahead</td></tr><tr><td><code>d</code></td><td>indices</td><td>Report the start/end index of every group</td></tr></tbody></table><h2>🔁 Replacement Patterns</h2><table><thead><tr><th>Token</th><th>Inserts</th></tr></thead><tbody><tr><td><code>$&amp;</code></td><td>The whole match</td></tr><tr><td><code>$\`</code></td><td>Everything before the match</td></tr><tr><td><code>$&#39;</code></td><td>Everything after the match</td></tr><tr><td><code>$1</code>, <code>$2</code></td><td>Capture group 1, 2, …</td></tr><tr><td><code>$&lt;name&gt;</code></td><td>A named capture group</td></tr><tr><td><code>$$</code></td><td>A literal dollar sign</td></tr></tbody></table><blockquote><p>ℹ️ Other tools spell these differently: <code>\\1</code> in <code>sed</code>, <code>\\g&lt;1&gt;</code> in Python, <code>\${1}</code> in Go.</p></blockquote><h2>🧪 Where the Groups Show Up (JavaScript)</h2><pre><code class="language-js">&#39;2026-08-22&#39;.match(/\\d+/g)              // [&#39;2026&#39;, &#39;08&#39;, &#39;22&#39;] — no groups with /g
[...&#39;a1b2&#39;.matchAll(/([a-z])(\\d)/g)]    // every match, with its groups
/(\\d+)/.exec(&#39;abc 42&#39;)                  // [&#39;42&#39;, &#39;42&#39;, index: 4, ...]
/\\d/.test(&#39;abc&#39;)                        // false
&#39;a1&#39;.replace(/(\\w)(\\d)/, (m, a, b) =&gt; b + a)   // &#39;1a&#39;
&#39;a, b;c&#39;.split(/[,;]\\s*/)               // [&#39;a&#39;, &#39;b&#39;, &#39;c&#39;]
</code></pre><h2>⚠️ Gotchas</h2><ul><li><strong><code>.</code> does not match newlines</strong> unless you set the <code>s</code> flag — a common surprise on multi-line input.</li><li><strong>A <code>/g</code> regex is stateful.</strong> Reusing the same object across <code>test()</code> calls advances <code>lastIndex</code> and skips matches; build a fresh one, or reset <code>lastIndex = 0</code>.</li><li><strong>Nested quantifiers backtrack catastrophically.</strong> <code>(a+)+$</code> against a long non-matching string can hang the process — avoid overlapping repetition, prefer possessive/atomic groups where the flavour has them.</li><li><strong>Escape user input</strong> before putting it in a pattern; in JS, <code>RegExp.escape()</code> where available, otherwise <code>s.replace(/[.*+?^\${}()|[\\]\\\\]/g, &#39;\\\\$&amp;&#39;)</code>.</li><li><strong>Don’t parse HTML with regex.</strong> Use a parser; regex cannot handle nesting.</li><li><strong>Backslashes double up in strings</strong>: <code>new RegExp(&#39;\\\\d+&#39;)</code> is the same pattern as <code>/\\d+/</code>.</li></ul><h2>📚 Resources</h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Regular_expressions">MDN — regular expressions</a></li><li><a href="https://regex101.com">regex101 — build and explain patterns</a></li><li><a href="https://leaverou.github.io/regexplained/">RegExplained</a></li><li><a href="https://www.regular-expressions.info/">Regular-Expressions.info</a></li></ul>`,36)]]))}};export{a as default};